#ifdef CONFIG_STATIC_INIT_GNU

SECTION_PROLOGUE(.init_array,,)
{
	/*
	 * The constructor functions are invoked in the order they appear in
	 * the .init_array section. The compiler places the constructors with
	 * priorities in sections named .init_array.NNNNN, where NNNNN is the
	 * priority padded with leading zeros to 5 digits. We sort those by
	 * name so that lower numbers are invoked first, followed by the
	 * constructors without priority in .init_array.
	 */
	PROVIDE_HIDDEN (__init_array_start = .);
	KEEP (*(SORT_BY_INIT_PRIORITY(.init_array.*) SORT_BY_INIT_PRIORITY(.ctors.*)))
	KEEP (*(.init_array .ctors))
	PROVIDE_HIDDEN (__init_array_end = .);
} GROUP_ROM_LINK_IN(RAMABLE_REGION, ROMABLE_REGION)

#elif defined(CONFIG_CPLUSPLUS)

SECTION_PROLOGUE(.ctors,,)
{
	/*
	 * The constructor list starts with a 32/64-bit count of the number
	 * of constructors, or -1 to indicate that the list is terminated by a
	 * NULL pointer. Next comes the list of pointers to the constructors
	 * to be invoked, and finally a NULL pointer to terminate the list.
	 */

#ifdef CONFIG_64BIT
	. = ALIGN(8);
	__CTOR_LIST__ = .;
	QUAD((__CTOR_END__ - __CTOR_LIST__) / 8 - 2)
	KEEP(*(SORT_BY_NAME(".ctors*")))
	QUAD(0)
	__CTOR_END__ = .;
#else
	. = ALIGN(4);
	__CTOR_LIST__ = .;
	LONG((__CTOR_END__ - __CTOR_LIST__) / 4 - 2)
	KEEP(*(SORT_BY_NAME(".ctors*")))
	LONG(0)
	__CTOR_END__ = .;
#endif
} GROUP_ROM_LINK_IN(RAMABLE_REGION, ROMABLE_REGION)

SECTION_PROLOGUE(.init_array,,)
{
	. = ALIGN(4);
	__init_array_start = .;
	KEEP(*(SORT_BY_NAME(".init_array*")))
	__init_array_end = .;
} GROUP_ROM_LINK_IN(RAMABLE_REGION, ROMABLE_REGION)

#endif
